import { Request, Response } from 'express';
import { 
  validateAdminCredentials, 
  generateAdminToken, 
  validateCouncilSecurityPin,
  safeStringCompare,
  hashPassword,
  verifyPassword
} from '../services/authService';
import { config } from '../config';
import { AuthenticatedRequest } from '../middleware/auth';
import { dataStore } from '../services/dataStore';
import { serverDb, doc, getDoc, setDoc, serverTimestamp } from '../services/firebaseServer';

export class AuthController {
  /**
   * POST /api/admin/login or /api/auth/login
   */
  public async login(req: Request, res: Response): Promise<void> {
    const username = (req.body.username || req.body.email || '').trim();
    const password = (req.body.password || '').trim();

    if (!username || !password) {
      res.status(400).json({
        success: false,
        message: 'Username/Email and Password are required.'
      });
      return;
    }

    // 1. Check Cloud Firestore for hashed admin credentials first
    if (serverDb) {
      try {
        const snap = await getDoc(doc(serverDb, 'admin_config', 'admin_portal_credentials'));
        if (snap.exists()) {
          const cloudConfig = snap.data();
          const cleanUser = username.toLowerCase().trim();
          const userMatch = (
            cleanUser === cloudConfig.username?.toLowerCase() ||
            cleanUser === cloudConfig.email?.toLowerCase() ||
            cleanUser === config.admin.superUsername ||
            (config.admin.superUsername.includes('@') && cleanUser === config.admin.superUsername.split('@')[0])
          );

          if (userMatch) {
            let passMatch = false;

            // Check modern salted hash
            if (cloudConfig.passwordHash && cloudConfig.passwordSalt) {
              passMatch = verifyPassword(password, cloudConfig.passwordHash, cloudConfig.passwordSalt);
            } 
            // Fallback & automatic migration for legacy plain password
            else if (cloudConfig.passwordPlain) {
              passMatch = safeStringCompare(password, cloudConfig.passwordPlain);
              if (passMatch) {
                // Auto-migrate to secure hash in background
                try {
                  const { hash, salt } = hashPassword(password);
                  await setDoc(doc(serverDb, 'admin_config', 'admin_portal_credentials'), {
                    username: config.admin.superUsername,
                    email: cloudConfig.email || config.admin.superUsername,
                    passwordHash: hash,
                    passwordSalt: salt,
                    passwordPlain: null, // Wipe legacy plain password
                    updatedAt: serverTimestamp()
                  }, { merge: true });
                } catch {
                  // non-blocking migration error
                }
              }
            }

            if (passMatch) {
              const user = {
                username: (username as string).trim(),
                email: cloudConfig.email || config.admin.superUsername,
                role: 'Council Administrator',
                organization: config.board.name
              };
              const token = generateAdminToken(user);
              res.json({
                success: true,
                token,
                user,
                message: 'Administrative authentication successful.'
              });
              return;
            }
          }
        }
      } catch (err: any) {
        console.warn('[AUTH] Firestore admin credentials check failed:', err?.message);
      }
    }

    // 2. Validate against environment variables
    const validation = validateAdminCredentials(username, password);

    if (validation.isValid) {
      const user = {
        username: (username as string).trim(),
        email: validation.email || config.admin.superUsername,
        role: validation.role || 'Administrator',
        organization: config.board.name
      };

      const token = generateAdminToken(user);

      res.json({
        success: true,
        token,
        user,
        message: 'Administrative authentication successful.'
      });
      return;
    }

    res.status(401).json({
      success: false,
      message: 'Invalid administrative credentials. Please verify your email and password.'
    });
  }

  /**
   * POST /api/auth/register (Student / Candidate Account Registration)
   */
  public async registerCandidate(req: Request, res: Response): Promise<void> {
    const { name, email, phone, course, dob, password, fatherName, motherName } = req.body;

    if (!name || !course) {
      res.status(400).json({
        success: false,
        message: 'Candidate Name and Course are mandatory fields for registration.'
      });
      return;
    }

    const currentYear = new Date().getFullYear();
    const regNo = `BSE/${currentYear}/${Math.floor(1000 + Math.random() * 9000)}`;
    const rollNo = `${currentYear}08${Math.floor(100 + Math.random() * 900)}`;

    const studentRecord = {
      id: `std-${Date.now()}`,
      regNo,
      rollNo,
      name: name.toUpperCase().trim(),
      fatherName: (fatherName || '').toUpperCase().trim(),
      motherName: (motherName || '').toUpperCase().trim(),
      dob: dob || '01-01-2010',
      gender: req.body.gender || 'Male',
      category: req.body.category || 'General',
      course,
      stream: req.body.stream || 'General',
      session: `${currentYear}-${currentYear + 1}`,
      centerCode: '10110901003',
      centerName: 'मध्य विद्यालय, अर्राहा, घैलाढ़',
      schoolNameHindi: 'मध्य विद्यालय, अर्राहा, घैलाढ़',
      udiseCode: '10110901003',
      mobile: phone || '7070530080',
      email: email || 'candidate@example.com',
      address: req.body.address || 'मधेपुरा, बिहार - 852113',
      photoUrl: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=200&auto=format&fit=crop&q=80',
      subjects: [
        { code: '081', name: 'हिन्दी', type: 'Theory' as const },
        { code: '082', name: 'गणित', type: 'Theory' as const },
        { code: '083', name: 'विज्ञान', type: 'Theory' as const },
        { code: '084', name: 'सामाजिक विज्ञान', type: 'Theory' as const },
        { code: '085', name: 'सामान्य ज्ञान', type: 'Theory' as const }
      ],
      registrationDate: new Date().toISOString().split('T')[0],
      status: 'Verified' as const,
      feeStatus: 'Paid' as const,
      examCenter: 'मध्य विद्यालय, अर्राहा, घैलाढ़ (10110901003)'
    };

    // Save in unified data store (which writes to Cloud Firestore `students`)
    await dataStore.saveStudent(studentRecord);

    // Also persist in `users` collection in Firestore if serverDb is ready
    if (serverDb) {
      try {
        const userId = email ? email.replace(/[^a-zA-Z0-9]/g, '_') : regNo.replace(/\//g, '_');
        await setDoc(doc(serverDb, 'users', userId), {
          uid: userId,
          regNo,
          rollNo,
          name: studentRecord.name,
          email: email || '',
          phone: phone || '',
          course,
          role: 'candidate',
          createdAt: serverTimestamp()
        }, { merge: true });
      } catch (err: any) {
        console.warn('[AUTH] Error storing user profile in Firestore:', err?.message);
      }
    }

    const token = generateAdminToken({
      username: regNo,
      email: email || '',
      role: 'Candidate',
      organization: config.board.name
    });

    res.json({
      success: true,
      message: 'Student Registration successfully registered in Cloud Firestore!',
      regNo,
      rollNo,
      token,
      student: studentRecord
    });
  }

  /**
   * POST /api/auth/candidate-login
   */
  public async candidateLogin(req: Request, res: Response): Promise<void> {
    const { identifier, dob } = req.body;

    if (!identifier) {
      res.status(400).json({
        success: false,
        message: 'Registration Number or Roll Number is required.'
      });
      return;
    }

    const student = await dataStore.getStudentByRegOrRoll(identifier);
    if (!student) {
      res.status(404).json({
        success: false,
        message: `Candidate record not found for '${identifier}'.`
      });
      return;
    }

    // If DOB is supplied, verify it
    if (dob && student.dob && student.dob.trim() !== dob.trim()) {
      res.status(401).json({
        success: false,
        message: 'Date of Birth does not match Council Records for this Registration Number.'
      });
      return;
    }

    const token = generateAdminToken({
      username: student.regNo,
      email: student.email || '',
      role: 'Candidate',
      organization: config.board.name
    });

    res.json({
      success: true,
      token,
      student,
      message: 'Candidate authentication successful.'
    });
  }

  /**
   * POST /api/admin/forgot-password or /api/auth/forgot-password
   */
  public async forgotPassword(req: Request, res: Response): Promise<void> {
    const { email } = req.body;
    const cleanEmail = (email || '').toLowerCase().trim();

    if (
      cleanEmail === config.admin.superUsername ||
      (config.admin.superUsername.includes('@') && cleanEmail === config.admin.superUsername.split('@')[0])
    ) {
      res.json({
        success: true,
        message: 'Admin account verified. Please enter the authorized Council Security PIN to proceed.'
      });
      return;
    }

    res.status(404).json({
      success: false,
      message: 'The email provided is not registered as an authorized Board Administrator.'
    });
  }

  /**
   * POST /api/admin/reset-password or /api/auth/reset-password
   */
  public async resetPassword(req: Request, res: Response): Promise<void> {
    const { email, newPassword, securityPin } = req.body;
    const cleanEmail = (email || '').toLowerCase().trim();

    const isAuthorizedAdmin = (
      cleanEmail === config.admin.superUsername ||
      (config.admin.superUsername.includes('@') && cleanEmail === config.admin.superUsername.split('@')[0])
    );

    const isPinValid = validateCouncilSecurityPin(securityPin);

    if (isAuthorizedAdmin && isPinValid) {
      if (!newPassword || newPassword.length < 8) {
        res.status(400).json({
          success: false,
          message: 'New password must be at least 8 characters.'
        });
        return;
      }

      // Hash password cryptographically with a unique random salt
      const { hash, salt } = hashPassword(newPassword.trim());

      // 1. Update runtime admin password
      config.admin.superPassword = newPassword.trim();

      // 2. Persist in Cloud Firestore `admin_config/admin_portal_credentials`
      // NEVER store plain text passwords or PINs!
      if (serverDb) {
        try {
          await setDoc(doc(serverDb, 'admin_config', 'admin_portal_credentials'), {
            username: config.admin.superUsername,
            email: cleanEmail,
            passwordHash: hash,
            passwordSalt: salt,
            passwordPlain: null, // Wipe legacy plain field
            updatedAt: serverTimestamp()
          }, { merge: true });
        } catch (err: any) {
          console.warn('[AUTH] Failed to save updated password hash to Firestore:', err?.message);
        }
      }

      res.json({
        success: true,
        message: 'Administrator password successfully updated and cryptographically hashed! You can now log in.'
      });
      return;
    }

    res.status(400).json({
      success: false,
      message: 'Password reset rejected. Invalid email or unauthorized Security PIN.'
    });
  }

  /**
   * GET /api/admin/me or /api/auth/me
   */
  public async getProfile(req: AuthenticatedRequest, res: Response): Promise<void> {
    if (!req.adminUser) {
      res.status(401).json({ success: false, message: 'Unauthenticated' });
      return;
    }

    res.json({
      success: true,
      user: req.adminUser
    });
  }
}

export const authController = new AuthController();
