import { Request, Response, NextFunction } from 'express';
import { verifyAdminToken, AdminUserPayload } from '../services/authService';

export interface AuthenticatedRequest extends Request {
  adminUser?: AdminUserPayload;
}

/**
 * Authentication middleware for protected administrative endpoints
 */
export function requireAdminAuth(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
  const authHeader = req.headers.authorization;
  if (!authHeader) {
    res.status(401).json({
      success: false,
      error: 'Unauthorized',
      message: 'Authorization token required. Please log into the BSEDRC Council Admin Portal.'
    });
    return;
  }

  const token = authHeader.startsWith('Bearer ')
    ? authHeader.slice(7).trim()
    : authHeader.trim();

  const user = verifyAdminToken(token);
  if (!user) {
    res.status(401).json({
      success: false,
      error: 'InvalidToken',
      message: 'Admin session expired or invalid. Please re-authenticate.'
    });
    return;
  }

  req.adminUser = user;
  next();
}

/**
 * Optional admin auth - if token is present, populates req.adminUser without blocking
 */
export function optionalAdminAuth(req: AuthenticatedRequest, res: Response, next: NextFunction): void {
  const authHeader = req.headers.authorization;
  if (authHeader) {
    const token = authHeader.startsWith('Bearer ')
      ? authHeader.slice(7).trim()
      : authHeader.trim();
    const user = verifyAdminToken(token);
    if (user) {
      req.adminUser = user;
    }
  }
  next();
}
